 36	/// The standard [`Allocator`] over a C allocation family, the [`CLenAlloc`]
 37	/// policy `P`; and, as a policy itself, the storage-only one over it.
 38	///
 39	/// Its standard counterpart is `std::alloc::System`, an `Allocator` over a
 40	/// heap; this one's heap is the C family's, so that what a `Box` or `Vec`
 41	/// over it allocates C may free, and what C allocated they may adopt.
 42	///
 43	/// `#[repr(transparent)]` over `P`, so with a unit-struct policy it is
 44	/// zero-sized and `Copy`, and `Box<T, CAllocator<P>>` is one pointer wide,
 45	/// C's `T *`; `Send` and `Sync` follow `P`, so a family that must free on the
 46	/// allocating thread keeps its boxes and vectors there (see
 47	/// [Thread safety](https://github.com/crustify-rs/ffibox/blob/main/docs/ownership.md#conventions)):
 48	///
 49	/// ```compile_fail,E0277
 50	/// # use ffibox::CAllocator;
 51	/// /// A family that frees on the allocating thread only.
 52	/// struct LocalHeap(core::marker::PhantomData<*const ()>);
 53	/// fn send<T: Send>() {}
 54	/// send::<CAllocator<LocalHeap>>();
 55	/// ```
 56	///
 57	/// ```
 58	/// use core::alloc::{Allocator, Layout};
 59	/// use ffibox::{CAllocator, RustAlloc};
 60	///
 61	/// let a = CAllocator::new(RustAlloc);
 62	/// let mut v: Vec<u32, CAllocator<RustAlloc>> = Vec::new_in(a);
 63	/// v.extend([1, 2, 3]); // grows through the family's realloc
 64	/// assert_eq!(v, [1, 2, 3]);
 65	/// // Beyond the family's alignment is an `AllocError`, never a misaligned block.
 66	/// assert!(a.allocate(Layout::from_size_align(64, 64).unwrap()).is_err());
 67	/// ```
 68	///
 69	/// # The allocator
 70	///
 71	/// - **Zero-sized requests never reach C.** `allocate` of size 0 returns
 72	///   [`Layout::dangling_ptr`], `deallocate` of size 0 does nothing, `grow`
 73	///   from size 0 allocates afresh and `shrink` to size 0 frees and returns a
 74	///   dangling pointer. So C's `malloc` is never asked for 0 bytes, and no
 75	///   dangling pointer reaches its `realloc` or `free`.
 76	/// - **Alignment beyond `P::ALIGN` is an [`AllocError`]**, from every
 77	///   allocating method; the typed paths ffibox offers
 78	///   ([`try_box`](Self::try_box), the policy impls and the conversions)
 79	///   refuse such a type at compile time instead.
 80	/// - **`grow` and `shrink` go through
 81	///   [`c_realloc_len`](CLenAlloc::c_realloc_len)**, the family's `realloc`
 82	///   where it has one: on failure the old block is untouched and still
 83	///   allocated, as the standard contract requires. `grow_zeroed` zeroes the
 84	///   bytes past the old size after it. A shrink to the same size keeps the
 85	///   block.
 86	/// - **No method unwinds**: if a policy's routine panics, the process aborts,
 87	///   as the standard `Allocator` requires.
 88	///
 89	/// Every block is exactly the size requested, so a `Box` or `Vec` hands
 90	/// [`c_drop_len`](CLenDrop::c_drop_len) the size the block was allocated
 91	/// with, as a free that takes a size needs.
 92	///
 93	/// # What it counts as allocated, and what fits
 94	///
 95	/// The standard `Allocator` lets a block be freed only with a layout that
 96	/// *fits* it. `CAllocator<P>` relaxes that, and the relaxation is what makes
 97	/// adopting C's buffers sound:
 98	///
 99	/// - Every live, non-empty buffer of `P`'s family, allocated by
100	///   `CAllocator<P>` or by C with the family's routines, is *currently
101	///   allocated* by every `CAllocator<P>` whose `P` releases it (every
102	///   instance of a stateless `P`).
103	/// - A layout *fits* such a buffer when its alignment is at most
104	///   `P::ALIGN` and its size is not 0 and is a length
105	///   [`c_drop_len`](CLenDrop::c_drop_len) accepts for the buffer: no larger
106	///   than the allocation, and exactly its size when the family's free takes
107	///   a size. `deallocate`, `grow` and `shrink` ignore the alignment, and a
108	///   free that ignores the size ignores the layout's size too.
109	///
110	/// So `Vec::from_raw_parts_in(ptr, len, len, a)` adopts `len` elements C
111	/// allocated with `malloc` and never recorded a capacity for, where the
112	/// family's free ignores the size: the Vec frees, grows and shrinks it with
113	/// `len` elements' bytes, which `free` and `realloc` accept. Under a free
114	/// that takes the size, `len` must be exactly the allocation's. A size of 0
115	/// fits no C buffer: a buffer C allocated with 0 bytes (`malloc(0)`'s
116	/// non-NULL result) adopted with capacity 0 is leaked, never freed, so
117	/// [`CVec`]'s conversion frees it first.
118	///
119	/// # As a policy
120	///
121	/// `CAllocator<P>` is also a storage-only policy over the same family, as
122	/// [`RustAlloc`](crate::RustAlloc) is over Rust's:
123	///
124	/// | Owner | Through |
125	/// |-------|---------|
126	/// | `CBox<Foo, CAllocator<P>>` | [`CBox::new`](crate::CBox::new) / [`new_zeroed`](crate::CBox::new_zeroed) for a [`CZeroable`] `Foo`, [`CBox::new_uninit`](crate::CBox::new_uninit) otherwise; released by dropping the `Foo` in place and freeing its `size_of::<Foo>()` bytes, as a `Box` is |
127	/// | `CStrBox<CAllocator<P>>` | [`CStrBox::from_c_str`](crate::CStrBox::from_c_str), copying into `strlen + 1` bytes; freed with that length |
128	/// | `CVec<T, CAllocator<P>>` | everything `CVec<T, P>` does, forwarded to `P` |
129	///
130	/// Zero-sized objects, and objects aligned beyond `P::ALIGN`, are refused at
131	/// compile time.
132	#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Hash)]
133	#[repr(transparent)]
134	pub struct CAllocator<P>(P);
135	
136	impl<P> CAllocator<P> {
137	    /// The allocator over the family `policy` belongs to.
138	    #[inline]
139	    #[must_use]
140	    pub const fn new(policy: P) -> Self {
141	        Self(policy)
142	    }
143	
144	    /// The family's policy.
145	    #[inline]
146	    #[must_use]
147	    pub const fn policy(&self) -> &P {
148	        &self.0
149	    }
150	}
151	
152	impl<P: CLenAlloc> CAllocator<P> {
153	    /// One `T`'s layout, refusing zero-sized and over-aligned `T` at compile
154	    /// time: an object of the family is a non-empty buffer it aligns.
155	    #[inline(always)]
156	    pub(crate) const fn object_layout<T>() -> Layout {
157	        const {
158	            assert!(
159	                core::mem::size_of::<T>() != 0,
160	                "a zero-sized T has no storage in a C allocation family"
161	            );
162	            assert!(
163	                core::mem::align_of::<T>() <= P::ALIGN,
164	                "the family's allocator cannot align T"
165	            );
166	        }
167	        Layout::new::<T>()
168	    }
169	
170	    /// A block of `layout`'s size from the family, or the dangling block of
171	    /// size 0.
172	    #[inline]
173	    fn alloc_block(&self, layout: Layout) -> Result<NonNull<[u8]>, AllocError> {
174	        if layout.align() > P::ALIGN {
175	            return Err(AllocError);
176	        }
177	        if layout.size() == 0 {
178	            return Ok(NonNull::slice_from_raw_parts(layout.dangling_ptr(), 0));
179	        }
180	        let ptr = self.0.c_alloc_len(layout.size()).ok_or(AllocError)?;
181	        Ok(NonNull::slice_from_raw_parts(ptr, layout.size()))
182	    }
183	
184	    /// Move a block of `old` to one of `new` through the family's `realloc`.
185	    ///
186	    /// # Safety
187	    ///
188	    /// As [`Allocator::grow`] or [`Allocator::shrink`], by which `new` is
189	    /// larger or smaller than `old`.
190	    #[inline]
191	    unsafe fn realloc_block(
192	        &self,
193	        ptr: NonNull<u8>,
194	        old: Layout,
195	        new: Layout,
196	    ) -> Result<NonNull<[u8]>, AllocError> {
197	        if new.align() > P::ALIGN {
198	            return Err(AllocError);
199	        }
200	        if old.size() == 0 {
201	            // A block of size 0 is the dangling one: nothing to move or free.
202	            return self.alloc_block(new);
203	        }
204	        if new.size() == 0 {
205	            // SAFETY: the caller passes a block `old` fits; it is freed once.
206	            unsafe { self.0.c_drop_len(ptr.as_ptr(), old.size()) };
207	            return Ok(NonNull::slice_from_raw_parts(new.dangling_ptr(), 0));
208	        }
209	        if new.size() == old.size() {
210	            // The block is aligned to `P::ALIGN >= new.align()` already.
211	            return Ok(NonNull::slice_from_raw_parts(ptr, old.size()));
212	        }
213	        // SAFETY: the caller passes a live block of the family that `old`
214	        // fits, so `old.size()` is a length `c_drop_len` accepts for it;
215	        // neither length is 0. On `None` the block is untouched.
216	        let moved = unsafe { self.0.c_realloc_len(ptr.as_ptr(), old.size(), new.size()) };
217	        let moved = moved.ok_or(AllocError)?;
218	        Ok(NonNull::slice_from_raw_parts(moved, new.size()))
219	    }
220	}
