224	impl<P: CLenAlloc> CAllocator<P> {
225	    /// `value` in a fresh box of the family, or [`AllocError`] if the
226	    /// allocation fails, dropping `value` — `Box::try_new_in(value, self)`,
227	    /// which std has not stabilized; [`Box::new_in`](alloc::boxed::Box::new_in) aborts on that failure
228	    /// instead. A zero-sized `T` allocates nothing, as a `Box` of one never
229	    /// does. A `T` aligned beyond the family's `ALIGN` is refused at compile
230	    /// time:
231	    ///
232	    /// ```compile_fail,E0080
233	    /// # use ffibox::{CAllocator, RustAlloc};
234	    /// #[repr(align(32))]
235	    /// struct Wide(u8);
236	    /// // `RustAlloc`'s buffers are 16-aligned.
237	    /// let _ = CAllocator::new(RustAlloc).try_box(Wide(0));
238	    /// ```
239	    #[inline]
240	    pub fn try_box<T>(self, value: T) -> Result<alloc::boxed::Box<T, Self>, AllocError> {
241	        const {
242	            assert!(
243	                core::mem::align_of::<T>() <= P::ALIGN,
244	                "the family's allocator cannot align T"
245	            );
246	        }
247	        let ptr = self.allocate(Layout::new::<T>())?.cast::<T>();
248	        // SAFETY: `ptr` is a fresh block of `T`'s layout from `self` (the
249	        // dangling one for a zero-sized `T`, which `Box` never frees),
250	        // written once with `value` and then owned by the box.
251	        unsafe {
252	            ptr.as_ptr().write(value);
253	            Ok(alloc::boxed::Box::from_non_null_in(ptr, self))
254	        }
255	    }
256	}
