258	/// Aborts the process if dropped: armed around a policy's routines, which
259	/// the standard `Allocator` forbids to unwind, and disarmed with
260	/// `mem::forget` once they return.
261	struct AbortOnUnwind;
262	
263	impl Drop for AbortOnUnwind {
264	    #[inline]
265	    fn drop(&mut self) {
266	        crate::refs::abort_process()
267	    }
268	}
269	
270	/// Run `f`, aborting rather than unwinding out of it.
271	#[inline(always)]
272	fn no_unwind<R>(f: impl FnOnce() -> R) -> R {
273	    let guard = AbortOnUnwind;
274	    let r = f();
275	    core::mem::forget(guard);
276	    r
277	}
