279	// SAFETY: every non-empty block is a fresh allocation of the family
280	// (`c_alloc_len`, `c_realloc_len`), uniquely owned, of exactly the size
281	// requested and aligned to `P::ALIGN >= layout.align()` (larger alignments
282	// are refused), and it stays valid until `deallocate`, a successful `grow` or
283	// `shrink`, or C frees it: `CAllocator` has no `&mut` API and its drop frees
284	// nothing. Blocks of size 0 are dangling and well aligned, and never reach
285	// the family. The family's blocks are disjoint and end within the address
286	// space, as any allocator's. A failed `grow` or `shrink` leaves the block
287	// as it was (`c_realloc_len`'s contract). `deallocate` and the moves hand
288	// `c_drop_len` / `c_realloc_len` the block's size, which fits it as the
289	// docs above define. No method unwinds (`no_unwind`), none reads or writes a
290	// block the caller holds beyond what `grow_zeroed` zeroes.
291	unsafe impl<P: CLenAlloc> Allocator for CAllocator<P> {
292	    #[inline]
293	    fn allocate(&self, layout: Layout) -> Result<NonNull<[u8]>, AllocError> {
294	        no_unwind(|| self.alloc_block(layout))
295	    }
296	
297	    #[inline]
298	    unsafe fn deallocate(&self, ptr: NonNull<u8>, layout: Layout) {
299	        if layout.size() == 0 {
300	            // The dangling block of size 0: never the family's.
301	            return;
302	        }
303	        // SAFETY: the caller passes a block of the family `layout` fits, so
304	        // its size is a length `c_drop_len` accepts; it is freed once.
305	        no_unwind(|| unsafe { self.0.c_drop_len(ptr.as_ptr(), layout.size()) })
306	    }
307	
308	    #[inline]
309	    unsafe fn grow(
310	        &self,
311	        ptr: NonNull<u8>,
312	        old_layout: Layout,
313	        new_layout: Layout,
314	    ) -> Result<NonNull<[u8]>, AllocError> {
315	        // SAFETY: the caller upholds `grow`'s contract.
316	        no_unwind(|| unsafe { self.realloc_block(ptr, old_layout, new_layout) })
317	    }
318	
319	    #[inline]
320	    unsafe fn grow_zeroed(
321	        &self,
322	        ptr: NonNull<u8>,
323	        old_layout: Layout,
324	        new_layout: Layout,
325	    ) -> Result<NonNull<[u8]>, AllocError> {
326	        // SAFETY: the caller upholds `grow_zeroed`'s contract, which is
327	        // `grow`'s.
328	        let block = unsafe { self.grow(ptr, old_layout, new_layout) }?;
329	        // SAFETY: the new block holds `new_layout.size() >= old_layout.size()`
330	        // bytes, the caller's from here on; the ones past the old size are
331	        // zeroed, as `grow_zeroed` promises.
332	        unsafe {
333	            block
334	                .cast::<u8>()
335	                .add(old_layout.size())
336	                .write_bytes(0, new_layout.size() - old_layout.size())
337	        };
338	        Ok(block)
339	    }
340	
341	    #[inline]
342	    unsafe fn shrink(
343	        &self,
344	        ptr: NonNull<u8>,
345	        old_layout: Layout,
346	        new_layout: Layout,
347	    ) -> Result<NonNull<[u8]>, AllocError> {
348	        // SAFETY: the caller upholds `shrink`'s contract.
349	        no_unwind(|| unsafe { self.realloc_block(ptr, old_layout, new_layout) })
350	    }
351	}
