357	// SAFETY: `c_drop` drops the `T` in place and frees its `size_of::<T>()`
358	// bytes once, the length `c_alloc` / `c_alloc_zeroed` allocated them with —
359	// what dropping a `Box<T, CAllocator<P>>` does.
360	unsafe impl<P: CLenAlloc, T: CCell> CDrop<T> for CAllocator<P> {
361	    #[inline]
362	    unsafe fn c_drop(&self, ptr: NonNull<T>) {
363	        let size = Self::object_layout::<T>().size();
364	        // SAFETY: the caller owns a live `T` in a `size_of::<T>()`-byte
365	        // buffer of the family; it is dropped, then freed, once.
366	        unsafe {
367	            core::ptr::drop_in_place(ptr.as_ptr());
368	            self.0.c_drop_len(ptr.as_ptr().cast(), size);
369	        }
370	    }
371	}
