373	// SAFETY: storage for a `T` that holds no `T` yet is freed without being
374	// read, with the length it was allocated with.
375	unsafe impl<P: CLenAlloc, T: CCell> CDrop<MaybeUninit<T>> for CAllocator<P> {
376	    #[inline]
377	    unsafe fn c_drop(&self, ptr: NonNull<MaybeUninit<T>>) {
378	        let size = Self::object_layout::<T>().size();
379	        // SAFETY: the caller owns a `size_of::<T>()`-byte buffer of the
380	        // family; it is freed once.
381	        unsafe { self.0.c_drop_len(ptr.as_ptr().cast(), size) }
382	    }
383	}
