385	// SAFETY: a fresh, uniquely-owned buffer of `size_of::<T>()` bytes aligned to
386	// `P::ALIGN >= align_of::<T>()` (checked at compile time), which both `CDrop`
387	// impls above free without the uninitialised one reading it.
388	unsafe impl<P: CLenAlloc, T: CCell> CAlloc<T> for CAllocator<P> {
389	    #[inline]
390	    fn c_alloc(&self) -> Option<NonNull<MaybeUninit<T>>> {
391	        let size = Self::object_layout::<T>().size();
392	        // The size is not 0 (`object_layout`).
393	        self.0.c_alloc_len(size).map(NonNull::cast)
394	    }
