400	    #[inline]

content.content:
400	    #[inline]
401	    fn c_alloc_zeroed(&self) -> Option<NonNull<T>> {
402	        let size = Self::object_layout::<T>().size();
403	        let ptr = self.0.c_alloc_len(size)?;
404	        // SAFETY: a fresh allocation of `size` bytes, uniquely owned.
405	        unsafe { ptr.as_ptr().write_bytes(0, size) };
406	        Some(ptr.cast())
407	    }
