498	/// `Box<T, CAllocator<P>>` as the [`CBox`] it is: the same pointer, the same
499	/// allocator, nothing copied — `Box` → `CBox`, where C keeps or frees the
500	/// object from now on (`into_c` hands it the pointer). Dropping either
501	/// drops the `T` in place and frees its bytes through the family.
502	///
503	/// A box of a zero-sized `T` holds a dangling pointer that was never
504	/// allocated, which C would free; a `T` aligned beyond the family's `ALIGN`
505	/// has no buffer of the family. Both are refused at compile time:
506	///
507	/// ```compile_fail,E0080
508	/// # use ffibox::{define_ctype, CAllocator, CBox, CZeroable, RustAlloc};
509	/// #[repr(C)]
510	/// pub struct empty_st {}
511	/// define_ctype!(Empty, EmptyRef, EmptyMut, empty_st);
512	/// # // SAFETY: no bytes.
513	/// # unsafe impl CZeroable for Empty {}
514	/// let b = Box::new_in(Empty::zeroed(), CAllocator::new(RustAlloc));
515	/// let _ = CBox::from(b);
516	/// ```
517	///
518	/// ```compile_fail,E0080
519	/// # use ffibox::{define_ctype, CAllocator, CBox, CZeroable, RustAlloc};
520	/// #[repr(C, align(32))]
521	/// pub struct wide_st { x: u8 }
522	/// define_ctype!(Wide, WideRef, WideMut, wide_st);
523	/// # // SAFETY: any byte.
524	/// # unsafe impl CZeroable for Wide {}
525	/// # let b = Box::new(Wide::zeroed());
526	/// # let b = unsafe { Box::from_raw_in(Box::into_raw(b), CAllocator::new(RustAlloc)) };
527	/// let _ = CBox::from(b); // `RustAlloc`'s buffers are 16-aligned
528	/// ```
529	///
530	/// The policy is stateless, as every [`CBox`]'s is.
531	#[cfg(feature = "alloc")]
532	#[cfg_attr(docsrs, doc(cfg(feature = "alloc")))]
533	impl<T: CCell, P: CLenAlloc> From<alloc::boxed::Box<T, CAllocator<P>>> for CBox<T, CAllocator<P>> {
534	    #[inline]
535	    fn from(b: alloc::boxed::Box<T, CAllocator<P>>) -> Self {
536	        let _ = CAllocator::<P>::object_layout::<T>();
537	        let (ptr, a) = alloc::boxed::Box::into_non_null_with_allocator(b);
538	        // SAFETY: the box owned a live `T` in a non-empty block of the family
539	        // (`T` is not zero-sized), which `CBox`'s `CDrop<T>` frees as the box
540	        // did; nothing else uses it.
541	        unsafe { CBox::from_non_null_with(ptr, a) }
542	    }
543	}
