662	    fn try_from(v: alloc::vec::Vec<T, CAllocator<P>>) -> Result<Self, Self::Error> {
663	        let elem = CAllocator::<P>::object_layout::<T>();
664	        let (ptr, len, cap, a) = v.into_raw_parts_with_allocator();
665	        if cap == 0 {
666	            // No allocation: the dangling pointer stays in Rust.
667	            return Ok(Self::empty_with(a));
668	        }
