670	        // `cap * size_of::<T>() <= isize::MAX` bytes from `a`, aligned for `T`.
671	        let (base, held) = unsafe {
672	            (
673	                NonNull::new_unchecked(ptr),
674	                Layout::from_size_align_unchecked(cap * elem.size(), elem.align()),
675	            )
676	        };
677	        if len == 0 {
678	            // SAFETY: the block the `Vec` held, with its layout; freed once.
679	            unsafe { a.deallocate(base.cast(), held) };
680	            return Ok(Self::empty_with(a));
681	        }
682	        let base = if len == cap {
683	            base
684	        } else {
685	            // SAFETY: `len < cap`, so the size is in range.
686	            let used =
687	                unsafe { Layout::from_size_align_unchecked(len * elem.size(), elem.align()) };
688	            // SAFETY: the block the `Vec` held, which `held` fits; on failure
689	            // it is untouched.
690	            match unsafe { a.shrink(base.cast(), held, used) } {
691	                Ok(block) => block.cast::<T>(),
692	                Err(AllocError) => {
693	                    // SAFETY: the parts the `Vec` gave up, unchanged.
694	                    let v = unsafe { Self::Error::from_raw_parts_in(ptr, len, cap, a) };
695	                    return Err(v);
696	                }
697	            }
698	        };
699	        // SAFETY: `len` initialised `T` in a block of the family exactly
700	        // `len * size_of::<T>()` bytes long, aligned for `T`, which the
701	        // `CVec`'s policy frees with that length; nothing else owns it.
702	        Ok(unsafe { Self::from_non_null_parts_with(base, len, a) })
703	    }
704	}

