  1	//! `CAllocator`, the standard `Allocator` over a C allocation family, over a
  2	//! stand-in family of `extern "C"` routines on `std::alloc::System`, so that
  3	//! Miri runs it. The family records every buffer it hands out, so a test sees
  4	//! each call C would get: a `free` of a pointer it never returned (a dangling
  5	//! one) is counted, not performed, and so is a sized free given the wrong
  6	//! size, a `malloc(0)` and a buffer never freed.
  7	
  8	#![cfg(feature = "alloc")]
  9	#![allow(missing_docs)]
 10	
 11	use core::alloc::{AllocError, Allocator, Layout};
 12	use core::ffi::{CStr, c_void};
 13	use core::mem::size_of;
 14	use core::ptr::{NonNull, null_mut};
 15	use std::alloc::{GlobalAlloc, System};
 16	use std::cell::RefCell;
 17	use std::collections::HashMap;
 18	
 19	use ffibox::{
 20	    CAllocator, CBox, CLenAlloc, CStrBox, CVec, CZeroable, define_ctype, impl_clenalloc,
 21	    impl_clendrop,
 22	};
 23	
 24	// ---------------------------------------------------------------------------
 25	// The stand-in C family
 26	// ---------------------------------------------------------------------------
 27	
 28	/// Every buffer is preceded by a header this wide, which keeps it 16-aligned.
 29	const HDR: usize = 16;
 30	
 31	#[derive(Default)]
 32	struct Track {
 33	    /// Live buffers: address to size.
 34	    live: HashMap<usize, usize>,
 35	    mallocs: usize,
 36	    zero_mallocs: usize,
 37	    reallocs: usize,
 38	    frees: usize,
 39	    /// `free` or `realloc` of a pointer the family did not hand out.
 40	    bad_frees: usize,
 41	    /// A sized free given another size than the buffer's.
 42	    size_mismatches: usize,
 43	    fail_malloc: bool,
 44	    fail_realloc: bool,
 45	}
 46	
 47	thread_local! {
 48	    static TRACK: RefCell<Track> = RefCell::new(Track::default());
 49	}
 50	
 51	fn with<R>(f: impl FnOnce(&mut Track) -> R) -> R {
 52	    TRACK.with(|t| f(&mut t.borrow_mut()))
 53	}
 54	
 55	/// What a test reads back.
 56	#[derive(Debug, Default, PartialEq, Eq, Clone, Copy)]
 57	struct Counts {
 58	    live: usize,
 59	    mallocs: usize,
 60	    zero_mallocs: usize,
 61	    reallocs: usize,
 62	    frees: usize,
 63	    bad_frees: usize,
 64	    size_mismatches: usize,
 65	}
 66	
 67	fn counts() -> Counts {
 68	    with(|t| Counts {
 69	        live: t.live.len(),
 70	        mallocs: t.mallocs,
 71	        zero_mallocs: t.zero_mallocs,
 72	        reallocs: t.reallocs,
 73	        frees: t.frees,
 74	        bad_frees: t.bad_frees,
 75	        size_mismatches: t.size_mismatches,
 76	    })
 77	}
 78	
 79	/// Starts a test on a clean family, and checks on drop that it ended with
 80	/// nothing live and no bad call.
 81	struct Fresh;
 82	
 83	fn fresh() -> Fresh {
 84	    with(|t| *t = Track::default());
 85	    Fresh
 86	}
 87	
 88	impl Drop for Fresh {
 89	    fn drop(&mut self) {
 90	        if std::thread::panicking() {
 91	            return;
 92	        }
 93	        let c = counts();
 94	        assert_eq!(c.live, 0, "a buffer was never freed: {c:?}");
 95	        assert_eq!(
 96	            c.bad_frees, 0,
 97	            "C was handed a pointer it never allocated: {c:?}"
 98	        );
 99	        assert_eq!(
100	            c.size_mismatches, 0,
101	            "a sized free got the wrong size: {c:?}"
102	        );
103	        assert_eq!(c.zero_mallocs, 0, "C's malloc was asked for 0 bytes: {c:?}");
104	    }
105	}
106	
107	fn raw_layout(size: usize) -> Layout {
108	    Layout::from_size_align(size + HDR, 16).unwrap()
109	}
110	
111	/// A fresh buffer, untracked.
112	unsafe fn raw_alloc(size: usize) -> *mut u8 {
113	    // SAFETY: the layout is never zero-sized.
114	    let base = unsafe { System.alloc(raw_layout(size)) };
115	    if base.is_null() {
116	        return null_mut();
117	    }
118	    // SAFETY: `HDR` bytes into a `size + HDR`-byte allocation.
119	    unsafe { base.add(HDR) }
120	}
121	
122	/// # Safety
123	///
124	/// `p` must be a live `raw_alloc(size)` buffer.
125	unsafe fn raw_free(p: *mut u8, size: usize) {
126	    // SAFETY: the caller passes a buffer `raw_alloc` returned.
127	    unsafe { System.dealloc(p.sub(HDR), raw_layout(size)) }
128	}
129	
130	/// The family's `malloc`.
131	unsafe extern "C" fn heap_malloc(size: usize) -> *mut c_void {
132	    if size == 0 {
133	        with(|t| t.zero_mallocs += 1);
134	    }
135	    if with(|t| t.fail_malloc) {
136	        return null_mut();
137	    }
138	    // SAFETY: any size.
139	    let p = unsafe { raw_alloc(size) };
140	    if !p.is_null() {
141	        with(|t| {
142	            t.live.insert(p.addr(), size);
143	            t.mallocs += 1;
144	        });
145	    }
146	    p.cast()
147	}
148	
149	/// The family's `free`; NULL is a no-op, as for C's.
150	unsafe extern "C" fn heap_free(p: *mut c_void) {
151	    if p.is_null() {
152	        return;
153	    }
154	    let Some(size) = with(|t| t.live.remove(&p.addr())) else {
155	        with(|t| t.bad_frees += 1);
156	        return;
157	    };
158	    with(|t| t.frees += 1);
