163	/// The family's `realloc`.
164	unsafe extern "C" fn heap_realloc(p: *mut c_void, size: usize) -> *mut c_void {
165	    if p.is_null() {
166	        // SAFETY: as `malloc`.
167	        return unsafe { heap_malloc(size) };
168	    }
169	    let Some(old) = with(|t| t.live.get(&p.addr()).copied()) else {
170	        with(|t| t.bad_frees += 1);
171	        return null_mut();
172	    };
173	    if size == 0 {
174	        with(|t| t.zero_mallocs += 1);
175	    }
176	    if with(|t| t.fail_realloc) {
177	        return null_mut();
178	    }
179	    // SAFETY: any size.
180	    let new = unsafe { raw_alloc(size) };
181	    if new.is_null() {
182	        return null_mut();
183	    }
184	    // SAFETY: `p` holds `old` bytes and `new` `size`, disjoint; `p` is freed
185	    // once, after.
186	    unsafe {
187	        core::ptr::copy_nonoverlapping(p.cast::<u8>(), new, old.min(size));
188	        raw_free(p.cast(), old);
189	    }
190	    with(|t| {
191	        t.live.remove(&p.addr());
192	        t.live.insert(new.addr(), size);
193	        t.reallocs += 1;
194	    });
195	    new.cast()
196	}
