//! Review probe: `into_box`'s two stated conditions hold, yet safe code
//! reaches UB through the `Box`, since C may have left the object holding
//! bytes that are not a valid `T` value (here a `_Bool` of 2).
#![cfg(feature = "alloc")]
use ffibox::{define_ctype, CAllocator, CBox, CZeroable, RustAlloc};

#[repr(C)]
pub struct flag_st {
    on: bool,
}
define_ctype!(Flag, FlagRef, FlagMut, flag_st);
// SAFETY: all-zero is `on == false`, and `Flag` is not address-sensitive.
unsafe impl CZeroable for Flag {}

#[test]
fn into_box_lets_safe_code_copy_a_value_c_left_invalid() {
    let c: CBox<Flag, CAllocator<RustAlloc>> = CBox::new_zeroed().unwrap();
    // "C" stores 2 in the `_Bool`, as a C routine behind a `FlagMut` may.
    unsafe { c.as_c_ptr().cast::<u8>().write(2) };
    // SAFETY, as documented: `Flag` is CZeroable, so not address-sensitive,
    // and nothing but the box reaches it.
    let b = unsafe { c.into_box() };
    let v: Flag = *b; // safe: a typed move out of the box
    core::mem::forget(v);
}
EOF
